    }

    #[inline]
    fn serialize_map(self, len: Option<usize>) -> Result<Self::SerializeMap> {
        Ok(SerializeMap {
            lua: self.lua,
            key: None,
            table: self.lua.create_table_with_capacity(0, len.unwrap_or(0))?,
